#!/usr/bin/env node
// Generates from contracts/crm/crm-api.json (single source):
//   docs/crm/03-RBAC_MATRIX.md, docs/crm/04-CRM_API.md and, with --crm <dir>, <dir>/src/contract.gen.ts.
// --check: fail when a generated file differs from the committed one (used by tests/crm-stage4-contract.test.mjs).
import {readFileSync,writeFileSync,existsSync} from 'node:fs';import {fileURLToPath} from 'node:url';import path from 'node:path';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const args=process.argv.slice(2);const check=args.includes('--check');const crmDir=args.includes('--crm')?args[args.indexOf('--crm')+1]:null;
const c=JSON.parse(readFileSync(root+'/contracts/crm/crm-api.json','utf8'));
const roles=c.roles;const roleUk={OWNER:'Власник',MANAGER:'Менеджер',WAREHOUSE:'Склад',SUPPORT:'Підтримка',ACCOUNTANT:'Бухгалтер'};

function tsType(s,depth=0){
 if(typeof s==='string')return s;if(!s)return 'unknown';
 if(s.$ref)return s.$ref;if(s.const!==undefined)return JSON.stringify(s.const);if(s.enum)return s.enum.map(v=>JSON.stringify(v)).join(' | ');
 if(s.anyOf)return s.anyOf.map(x=>tsType(x,depth)).join(' | ');if(s.allOf)return s.allOf.map(x=>tsType(x,depth)).join(' & ');
 const types=[].concat(s.type??[]);
 const one=t=>{
  if(t==='string')return 'string';if(t==='integer'||t==='number')return 'number';if(t==='boolean')return 'boolean';if(t==='null')return 'null';
  if(t==='array')return `${s.items?wrap(tsType(s.items,depth+1)):'unknown'}[]`;
  if(t==='object'){if(!s.properties)return 'Record<string, unknown>';const req=new Set(s.required??[]);const pad='  '.repeat(depth+1);
   const body=Object.entries(s.properties).map(([k,v])=>`${pad}${/^[a-z_][a-z0-9_]*$/i.test(k)?k:JSON.stringify(k)}${req.has(k)?'':'?'}: ${tsType(v,depth+1)};`).join('\n');
   return `{\n${body}\n${'  '.repeat(depth)}}`;}
  return 'unknown';};
 return types.length?types.map(one).join(' | '):'unknown';
}
const wrap=t=>/[|&]/.test(t)&&!t.startsWith('{')?`(${t})`:t;

function ts(){
 let out='// GENERATED by SITE dev/crm-contract-gen.mjs from contracts/crm/crm-api.json — do not edit by hand.\n/* eslint-disable */\n';
 out+=`${c.definitions.Role?'':'export type Role = '+roles.map(r=>JSON.stringify(r)).join(' | ')+';\n'}export type Permission = ${Object.keys(c.permissions).map(p=>JSON.stringify(p)).join(' | ')};\n\n`;
 for(const [name,def] of Object.entries(c.definitions))out+=`export type ${name} = ${tsType(def)};\n\n`;
 out+='export type RouteMeta = { id: string; method: "GET" | "POST" | "PUT"; path: string; permission: Permission | null; stepUp: boolean; version: boolean; idempotent: boolean; created: boolean };\n';
 out+='export const ROUTES = {\n'+c.routes.map(r=>`  ${JSON.stringify(r.id)}: { id: ${JSON.stringify(r.id)}, method: ${JSON.stringify(r.method)}, path: ${JSON.stringify(r.path)}, permission: ${JSON.stringify(r.permission)}, stepUp: ${!!r.step_up}, version: ${r.version==='required'}, idempotent: ${!!r.idempotent}, created: ${!!r.created} }`).join(',\n')+',\n} as const satisfies Record<string, RouteMeta>;\n\n';
 out+='export interface RouteTypes {\n'+c.routes.map(r=>`  ${JSON.stringify(r.id)}: { request: ${r.request??'never'}; response: ${r.response==='csv'?'Blob':r.response}; query: ${r.query??'never'} };`).join('\n')+'\n}\n';
 out+=`export const PERMISSIONS: Record<Permission, readonly Role[]> = ${JSON.stringify(c.permissions)};\n`;
 return out;
}
function rbac(){
 const perms=Object.keys(c.permissions);
 let out=`# CRM РУБІЖ — RBAC-матрица (этап 4)\n\n> Сгенерировано \`dev/crm-contract-gen.mjs\` из \`contracts/crm/crm-api.json\`. Не редактировать вручную. Проверка: \`tests/crm-stage4-rbac.test.mjs\` (каждый маршрут × каждая роль: разрешено → не 401/403/5xx; запрещено → 403; без входа → 401; сессия покупателя → 401).\n\n`;
 out+=`Права, выполняемые только OWNER независимо от таблицы: \`payment.refund.execute\`, \`payment.manual_reconcile\`, \`payment.review\`, \`settings.system\`, \`staff.manage\`, \`supplier.manage\`, \`export.full\`, \`shipment.resolve_unknown\`, \`shipment.manual_deliver\`, \`inventory.return\` (\`staff/auth.php\`, \`crmPermit\`). MANAGER меняет только свои и неназначенные заказы (403 \`ORDER_NOT_ASSIGNED\`); платежи видит только своих заказов. WAREHOUSE не получает денежных полей (\`crmRedactOrder\`). Повторный вход (step-up ≤ 15 мин) — столбец «↻».\n\n`;
 out+=`## Права × роли\n\n| Право | ${roles.map(r=>roleUk[r]).join(' | ')} |\n|---|${roles.map(()=>':-:').join('|')}|\n`;
 for(const p of perms)out+=`| \`${p}\` | ${roles.map(r=>c.permissions[p].includes(r)?'✓':'—').join(' | ')} |\n`;
 if(c.field_visibility){out+=`\n## Поля × роли (видит / не видит)\n\nПроверка: \`tests/crm-stage4-fields.test.mjs\` — каждое поле × каждая роль по живому ответу Staff API. WAREHOUSE видит объявленную стоимость только как поле формы ТТН (в данных не отдаётся).\n\n| Поле | Право | ${roles.map(r=>roleUk[r]).join(' | ')} |\n|---|---|${roles.map(()=>':-:').join('|')}|\n`;for(const [k,f] of Object.entries(c.field_visibility))out+=`| ${f.label} (\`${k}\`) | \`${f.permission}\` | ${roles.map(r=>c.permissions[f.permission].includes(r)?'видит':'—').join(' | ')} |\n`;}
 out+=`\n## Эндпоинты × роли\n\n| Метод | Путь | Право | ↻ | Версия | Ключ | ${roles.map(r=>roleUk[r]).join(' | ')} |\n|---|---|---|:-:|:-:|:-:|${roles.map(()=>':-:').join('|')}|\n`;
 for(const r of c.routes){const allowed=r.auth==='public'?roles.map(()=>'публ.'):r.permission===null?roles.map(()=>'сесія'):roles.map(x=>c.permissions[r.permission].includes(x)?'200':'403');
  out+=`| ${r.method} | \`${r.path}\` | ${r.permission?'`'+r.permission+'`':'—'} | ${r.step_up?'↻':''} | ${r.version==='required'?'✓':''} | ${r.idempotent?'✓':''} | ${allowed.join(' | ')} |\n`;}
 return out;
}
function api(){
 let out=`# CRM РУБІЖ — API (этап 4)\n\n> Сгенерировано из \`contracts/crm/crm-api.json\` (\`dev/crm-contract-gen.mjs\`). Схемы запросов/ответов — в контракте; типы клиента — \`crm.rubizh/src/contract.gen.ts\`.\n\nБаза: \`${c.base}\`. Все маршруты — в \`docs/release-hardening/stage-2/00-SYSTEM_MAP.md\` (раздел Staff API).\n\n## Соглашения\n\n`;
 for(const [k,v] of Object.entries(c.conventions))out+=`- **${k}**: ${v}\n`;
 out+=`\n## Маршруты\n\n| ID | Метод | Путь | Право | Запрос | Ответ | Описание |\n|---|---|---|---|---|---|---|\n`;
 for(const r of c.routes)out+=`| \`${r.id}\`${r.deprecated?' (совм.)':''} | ${r.method} | \`${r.path}\` | ${r.permission?'`'+r.permission+'`':r.auth} | ${r.request?'`'+r.request+'`':r.query?'query `'+r.query+'`':'—'} | \`${r.response}\` | ${r.summary} |\n`;
 out+=`\n## Ошибки\n\nФормат: \`{ok:false, error:{code, message (укр.), details}, meta:{request_id, csrf}}\`. Сообщения — \`staff/router.php\` (\`crmMessages\`); внутренние тексты исключений не показываются (CRM-PHP-01).\n\n| HTTP | Коды |\n|---|---|\n| 400 | INVALID_REQUEST, INVALID_QUERY, INVALID_JSON, VERSION_REQUIRED, IDEMPOTENCY_KEY_REQUIRED, WEAK_PASSWORD, TOKEN_INVALID, REASON_REQUIRED, INVALID_ASSIGNEE, INVALID_PERIOD, TOTP_INVALID (включение) |\n| 401 | AUTH_REQUIRED, LOGIN_FAILED, TOTP_REQUIRED, TOTP_INVALID, STEP_UP_REQUIRED, REAUTH_FAILED |\n| 403 | PERMISSION_DENIED, ORDER_NOT_ASSIGNED, CSRF_INVALID, HTTPS_REQUIRED, TOTP_ENROLL_REQUIRED |\n| 404/405 | NOT_FOUND, METHOD_NOT_ALLOWED |\n| 409 | STALE_ORDER, IDEMPOTENCY_CONFLICT, PRICE_CHANGED, LINE_OUT_OF_STOCK, FEATURE_NOT_CONNECTED, ORDER_PAID, SHIPMENT_STARTED, INVOICE_OPEN, PACKING_NOT_ALLOWED, NOT_DELIVERED, TTN_EXISTS, DELIVERY_UNVERIFIED, LAST_OWNER_REQUIRED, REFUND_* , коды домена SITE |\n| 413 / 428 / 429 | PAYLOAD_TOO_LARGE / CHECK_REQUIRED / RATE_LIMITED |\n| 503 | CRM_DISABLED, STAFF_SCHEMA_REQUIRED, SERVICE_UNAVAILABLE, CRM_SECRET_KEY_MISSING |\n`;
 return out;
}
const files=[[root+'/docs/crm/03-RBAC_MATRIX.md',rbac()],[root+'/docs/crm/04-CRM_API.md',api()]];
if(crmDir)files.push([path.resolve(crmDir,'src/contract.gen.ts'),ts()]);
let drift=[];
for(const [f,body] of files){if(check){if(!existsSync(f)||readFileSync(f,'utf8')!==body)drift.push(f);}else writeFileSync(f,body);}
if(check&&drift.length){console.error('Generated files are out of date:\n'+drift.join('\n'));process.exit(1);}
console.log(check?'contract outputs up to date':'generated '+files.map(f=>path.relative(root,f[0])).join(', '));
